entries[23059] = { ["name"] = "Ring of the Dreadnaught", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+27 Stamina\nClasses: Warrior\nRequires Level 60\nEquip: Increases your dodge rating by 12.\n\nEquip: Increases defense rating by 15.\n\nDreadnaught's Battlegear (0/9)\nDreadnaught Bracers\nDreadnaught Breastplate\nDreadnaught Gauntlets\nDreadnaught Waistguard\nDreadnaught Helmet\nDreadnaught Legplates\nDreadnaught Pauldrons\nDreadnaught Sabatons\nRing of the Dreadnaught\n(2) Set : Increases the damage done by your Revenge ability by 75.\n(4) Set : Improves your chance to hit with Taunt and Challenging Shout by 5%.\n(6) Set : Improves your chance to hit with Sunder Armor, Devastate, Heroic Strike, Revenge, and Shield Slam by 5%.\n(8) Set : When your health drops below 20%, for the next 5 seconds healing spells cast on you help you to Cheat Death, increasing healing done by up to 160.\nSell Price:" }
entries[23060] = { ["name"] = "Bonescythe Ring", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+20 Strength\n+20 Agility\n+10 Stamina\nClasses: Rogue\nRequires Level 60\nEquip: Increases your hit rating by 10.\n\nBonescythe Armor (0/9)\nBonescythe Bracers\nBonescythe Breastplate\nBonescythe Gauntlets\nBonescythe Helmet\nBonescythe Legplates\nBonescythe Pauldrons\nBonescythe Sabatons\nBonescythe Waistguard\nBonescythe Ring\n(2) Set : Your normal melee swings have a chance to Invigorate you, healing you for 90 to 110.\n(4) Set : Your Backstab, Sinister Strike, and Hemorrhage critical hits cause you to regain 5 energy.\n(6) Set : Reduces the threat from your Backstab, Sinister Strike, Hemorrhage, and Eviscerate abilities.\n(8) Set : Your Eviscerate has a chance per combo point to reveal a flaw in your opponent's armor, granting a 100% critical hit chance for your next Backstab, Sinister Strike, or Hemorrhage.\nSell Price:" }
entries[23061] = { ["name"] = "Ring of Faith", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+16 Intellect\n+16 Spirit\nClasses: Priest\nRequires Level 60\nEquip: Increases healing done by up to 55 and damage done by up to 19 for all magical spells and effects.\n\nVestments of Faith (0/9)\nBelt of Faith\nBindings of Faith\nCirclet of Faith\nGloves of Faith\nLeggings of Faith\nRobe of Faith\nSandals of Faith\nShoulderpads of Faith\nRing of Faith\n(2) Set : Reduces the mana cost of your Renew spell by 12%.\n(4) Set : On Greater Heal critical hits, your target will gain Armor of Faith, absorbing up to 500 damage.\n(6) Set : Reduces the threat from your healing spells.\n(8) Set : Each spell you cast can trigger an Epiphany, increasing your mana regeneration by 24 for 30 sec. (Proc chance: 5%)\nSell Price:" }
entries[23062] = { ["name"] = "Frostfire Ring", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+10 Stamina\n+10 Intellect\nClasses: Mage\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 30.\n\nEquip: Increases your spell critical strike rating by 14.\n\nFrostfire Regalia (0/9)\nFrostfire Belt\nFrostfire Bindings\nFrostfire Circlet\nFrostfire Gloves\nFrostfire Leggings\nFrostfire Robe\nFrostfire Sandals\nFrostfire Shoulderpads\nFrostfire Ring\n(2) Set : Reduces cooldown on your Evocation by 1 minute.\n(4) Set : Gives your Mage Armor a chance when struck by a harmful spell to increase resistance against that school of magic by 35 for 30 sec. (Proc chance: 20%)\n(6) Set : Your damage spells have a chance to cause your target to take up to 200 increased damage from subsequent spells. (Proc chance: 20%)\n(8) Set : Your damage spells have a chance to displace you, causing the next spell cast to generate no threat. (Proc chance: 15%)\nSell Price:" }
entries[23063] = { ["name"] = "Plagueheart Ring", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+24 Stamina\nClasses: Warlock\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 29.\n\nPlagueheart Raiment (0/9)\nPlagueheart Belt\nPlagueheart Bindings\nPlagueheart Circlet\nPlagueheart Gloves\nPlagueheart Leggings\nPlagueheart Robe\nPlagueheart Sandals\nPlagueheart Shoulderpads\nPlagueheart Ring\n(2) Set : Your Shadow Bolts now have a chance to heal you for 270 to 330.\n(4) Set : Increases damage caused by your Corruption by 12%.\n(6) Set : Your spell critical hits generate 25% less threat. In addition, Corruption, Immolate, Curse of Agony, and Siphon Life generate 25% less threat.\n(8) Set : Reduces health cost of your Life Tap by 12%.\nSell Price:" }
entries[23064] = { ["name"] = "Ring of the Dreamwalker", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+16 Stamina\n+16 Intellect\n+16 Spirit\nClasses: Druid\nRequires Level 60\nEquip: Increases healing done by up to 37 and damage done by up to 13 for all magical spells and effects.\n\nDreamwalker Raiment (0/9)\nDreamwalker Boots\nDreamwalker Girdle\nDreamwalker Handguards\nDreamwalker Headpiece\nDreamwalker Legguards\nDreamwalker Spaulders\nDreamwalker Tunic\nDreamwalker Wristguards\nRing of the Dreamwalker\n(2) Set : Your Rejuvenation ticks have a chance to restore 60 mana, 8 energy, or 2 rage to your target.\n(4) Set : Reduces the mana cost of your Healing Touch, Regrowth, Rejuvenation, and Tranquility spells by 3%.\n(6) Set : Your initial cast and Regrowth ticks will increase the maximum health of your target by up to 50, stacking up to 7 times.\n(8) Set : On Healing Touch critical hits, you regain 30% of the mana cost of the spell.\nSell Price:" }
entries[23065] = { ["name"] = "Ring of the Earthshatterer", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+16 Stamina\n+16 Intellect\nClasses: Shaman\nRequires Level 60\nEquip: Increases healing done by up to 37 and damage done by up to 13 for all magical spells and effects.\n\nEquip: Restores 6 mana per 5 sec.\n\nThe Earthshatterer (0/9)\nEarthshatter Boots\nEarthshatter Girdle\nEarthshatter Handguards\nEarthshatter Headpiece\nEarthshatter Legguards\nEarthshatter Spaulders\nEarthshatter Tunic\nEarthshatter Wristguards\nRing of the Earthshatterer\n(2) Set : Reduces the mana cost of your totem spells by 12%.\n(4) Set : Increases the mana gained from your Mana Spring totems by 25%.\n(6) Set : Your Healing Wave and Lesser Healing Wave spells have a chance to imbue your target with Totemic Power. (Proc chance: 10%)\n(8) Set : Your Lightning Shield spell also grants you 15 mana per 5 sec. while active.\nSell Price:" }
entries[23066] = { ["name"] = "Ring of Redemption", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+16 Stamina\n+16 Intellect\nClasses: Paladin\nRequires Level 60\nEquip: Increases healing done by up to 37 and damage done by up to 13 for all magical spells and effects.\n\nEquip: Restores 6 mana per 5 sec.\n\nRedemption Armor (0/9)\nRedemption Boots\nRedemption Girdle\nRedemption Handguards\nRedemption Headpiece\nRedemption Legguards\nRedemption Spaulders\nRedemption Tunic\nRedemption Wristguards\nRing of Redemption\n(2) Set : Increases the amount healed by your Judgement of Light by 20.\n(4) Set : Reduces cooldown on your Lay on Hands by 12 min.\n(6) Set : Your Flash of Light and Holy Light spells have a chance to imbue your target with Holy Power. (Proc chance: 10%)\n(8) Set : Your Cleanse spell also heals the target for 200.\nSell Price:" }
entries[23067] = { ["name"] = "Ring of the Cryptstalker", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+20 Agility\nClasses: Hunter\nRequires Level 60\nEquip: Restores 6 mana per 5 sec.\n\nEquip: Increases attack power by 40.\n\nCryptstalker Armor (0/9)\nCryptstalker Boots\nCryptstalker Girdle\nCryptstalker Handguards\nCryptstalker Headpiece\nCryptstalker Legguards\nCryptstalker Spaulders\nCryptstalker Tunic\nCryptstalker Wristguards\nRing of the Cryptstalker\n(2) Set : Increases the duration of your Rapid Fire by 4 sec.\n(4) Set : While your pet is active, increases attack power by 50 for both you and your pet.\n(6) Set : Your ranged critical hits cause an Adrenaline Rush, granting you 50 mana.\n(8) Set : Reduces the mana cost of your Multi-Shot and Aimed Shot by 20.\nSell Price:" }
